func specStr(id int) string {
	if id <= 0 || id >= len(specStrs) {
		return ""
	}
	return specStrs[id]
}

// ── the interpreter ─────────────────────────────────────────────────────

type specState struct {
	buf strings.Builder
}

func specDump(node parser.Node) string {
	s := &specState{}
	s.node(node, 0)
	return strings.TrimRight(s.buf.String(), "\n")
}

func specIndent(d int) string { return strings.Repeat("    ", d) }

// fieldOf reads a (possibly dotted) field by name off a node.
func fieldOf(node parser.Node, path string) reflect.Value {
	v := reflect.ValueOf(node)
	for _, step := range strings.Split(path, ".") {
		if !v.IsValid() {
			return v
		}
		if v.Kind() == reflect.Ptr {
			if v.IsNil() {
				return reflect.Value{}
			}
			v = v.Elem()
		}
		if v.Kind() != reflect.Struct {
			return reflect.Value{}
		}
		v = v.FieldByName(step)
	}
	return v
}

func isNilVal(v reflect.Value) bool {
	switch v.Kind() {
	case reflect.Invalid:
		return true
	case reflect.Ptr, reflect.Interface, reflect.Slice, reflect.Map:
		return v.IsNil()
	}
	return false
}

// renderScalar produces the value text for one scalar field.
//
// `of` decides where the text comes from; `render` decides how a raw field
// value is formatted.  Keeping them separate matters: `kv("args", len(n.Arguments))`
// and `kv("type", typeString(n.Type))` are both "always printed", but one
// reads a slice length and the other reads a child node.
func (s *specState) renderScalar(node parser.Node, of, render int, src string,
	childVal parser.Node) string {
	v := fieldOf(node, src)
	switch of {
	case ofLen:
		if !v.IsValid() || v.Kind() != reflect.Slice {
			return "0"
		}
		return fmt.Sprintf("%d", v.Len())
	case ofType:
		if childVal == nil {
			return ""
		}
		if t, ok := childVal.(parser.Type); ok {
			return t.String()
		}
		return ""
	case ofNodeString:
		// No nil guard here: (*dumper).nodeString has none, and
		// fmt.Sprintf("%T", nil) is "<nil>", so a nil child renders as "<nil>".
		// (typeString is different -- it checks for nil and returns ".")
		return specNodeString(childVal)
	case ofLabelKind:
		if !v.IsValid() {
			return "none"
		}
		switch parser.LabelKind(v.Int()) {
		case parser.LabelNumeric:
			return "numeric"
		case parser.LabelText:
			return "text"
		default:
			return "none"
		}
	case ofLocal:
		// A prelude local is "nodeString(f), or \"\" when f is nil".  A bare
		// nodeString(f) renders nil as "<nil>", so the two are not the same.
		if render == rNodeString {
			if childVal == nil {
				return ""
			}
			return specNodeString(childVal)
		}
		return renderValue(v, render)
	case ofBare, ofSprintf, ofField:
		return renderValue(v, render)
	}
	return ""
}

// renderValue formats a raw reflect value according to `render`.
func renderValue(v reflect.Value, render int) string {
	if !v.IsValid() {
		return ""
	}
	if v.Kind() == reflect.Interface || v.Kind() == reflect.Ptr {
		if v.IsNil() {
			return ""
		}
		v = v.Elem()
	}
	switch render {
	case rBool:
		if v.Kind() == reflect.Bool {
			return fmt.Sprintf("%v", v.Bool())
		}
	case rInt:
		if v.Kind() >= reflect.Int && v.Kind() <= reflect.Int64 {
			return fmt.Sprintf("%d", v.Int())
		}
	case rFloat:
		if v.Kind() == reflect.Float64 || v.Kind() == reflect.Float32 {
			return fmt.Sprintf("%v", v.Float())
		}
	}
	if v.Kind() == reflect.String {
		return v.String()
	}
	return fmt.Sprintf("%v", v.Interface())
}

func specNodeString(node parser.Node) string {
	switch n := node.(type) {
	case *parser.Identifier:
		return n.Value
	case *parser.IntegerLiteral:
		return fmt.Sprintf("%d", n.Value)
	case *parser.FloatLiteral:
		return fmt.Sprintf("%v", n.Value)
	case *parser.StringLiteral:
		return n.Value
	case *parser.CharLiteral:
		return n.Value
	case *parser.BooleanLiteral:
		return fmt.Sprintf("%v", n.Value)
	case *parser.NilLiteral:
		return "nil"
	default:
		return strings.TrimPrefix(fmt.Sprintf("%T", n), "*parser.")
	}
}

// specSignature mirrors (*dumper).signature.
func (s *specState) signature(sig parser.FuncSignature, depth int) {
	if len(sig.GenericParams) > 0 {
		names := make([]string, 0, len(sig.GenericParams))
		for _, g := range sig.GenericParams {
			if g != nil {
				names = append(names, g.Value)
			}
		}
		fmt.Fprintf(&s.buf, "%sGenericParams: %s\n", specIndent(depth), strings.Join(names, ", "))
	}
	if sig.IsVariadic {
		var parts []string
		if sig.VariadicUnion != "" {
			parts = append(parts, "union: "+sig.VariadicUnion)
		}
		fmt.Fprintf(&s.buf, "%sVariadic{%s}\n", specIndent(depth), strings.Join(parts, ", "))
	}
	for _, p := range sig.Parameters {
		if p != nil {
			s.node(p, depth)
		}
	}
	for _, p := range sig.Results {
		if p != nil {
			s.node(p, depth)
		}
	}
}

func (s *specState) commentGroup(cg *parser.CommentGroup, depth int) {
	if cg == nil {
		return
	}
	for _, c := range cg.List {
		fmt.Fprintf(&s.buf, "%s//%s\n", specIndent(depth), c.Text)
	}
}

func (s *specState) comments(node parser.Node, depth int) {
	if doc, ok := node.(interface{ GetDoc() *parser.CommentGroup }); ok {
		if g := doc.GetDoc(); g != nil && len(g.List) > 0 {
			fmt.Fprintf(&s.buf, "%sDoc: //%s\n", specIndent(depth), g.List[0].Text)
		}
	}
	if c, ok := node.(interface{ GetComment() *parser.CommentGroup }); ok {
		if g := c.GetComment(); g != nil && len(g.List) > 0 {
			fmt.Fprintf(&s.buf, "%sComment: //%s\n", specIndent(depth), g.List[0].Text)
		}
	}
}

// ── the main walk ───────────────────────────────────────────────────────

func (s *specState) node(node parser.Node, depth int) {
	if node == nil {
		fmt.Fprintf(&s.buf, "%s<nil>\n", specIndent(depth))
		return
	}
	ki, ok := specKindIndex[reflect.TypeOf(node).Elem().Name()]
	if !ok {
		fmt.Fprintf(&s.buf, "%s<unknown %T>\n", specIndent(depth), node)
		return
	}
	k := specKinds[ki]
	// A scalar that renders rType/rNodeString reads a *child node*, so the
	// child list must be built in CHILD-instruction order before the header
	// line is printed.
	var childNodes []parser.Node
	for i := k.First; i < k.First+k.Num; i++ {
		if specTape[i].Op == opChild {
			childNodes = append(childNodes, nodeFromValue(fieldOf(node, specStr(specTape[i].A))))
		}
	}
	childAt := func(ord int) parser.Node {
		if ord >= 0 && ord < len(childNodes) {
			return childNodes[ord]
		}
		return nil
	}

	for i := k.First; i < k.First+k.Num; i++ {
		t := specTape[i]
		switch t.Op {
		case opHdr:
			name := specStr(t.A)
			nodeOf := specStr(t.C)
			absent := specStr(t.D)
			var parts []string
			for j := i + 1; j < k.First+k.Num && specTape[j].Op == opScalar; j++ {
				sc := specTape[j]
				label := specStr(sc.D & 0xFFFFFF)
				rend := sc.B & 0xFF
				ofk := sc.B >> 8
				src := specStr(sc.C)
				ref := sc.D >> 24
				val := s.renderScalar(node, ofk, rend, src, childAt(ref))
				if !scalarWanted(sc.A, rend, val) {
					continue
				}
				if label == "" {
					parts = append(parts, val)
				} else if rend == rBool && val == "true" && sc.A == pTrue {
					parts = append(parts, label+": true")
				} else {
					parts = append(parts, label+": "+val)
				}
			}
			body := strings.Join(parts, ", ")
			if nodeOf != "" {
				cv := fieldOf(node, nodeOf)
				if isNilVal(cv) {
					body = absent
				} else {
					body = s.renderScalar(node, ofNodeString, rNodeString, nodeOf, nodeFromValue(cv))
				}
			}
			if t.B&1 != 0 {
				fmt.Fprintf(&s.buf, "%s%s{%s}\n", specIndent(depth), name, body)
			} else {
				fmt.Fprintf(&s.buf, "%s%s\n", specIndent(depth), name)
			}
		case opComments:
			s.comments(node, depth+1)
		case opSig:
			v := fieldOf(node, "FuncSignature")
			if v.IsValid() {
				s.signature(v.Interface().(parser.FuncSignature), depth+1)
			}
		case opChild:
			v := fieldOf(node, specStr(t.A))
			if isNilVal(v) {
				if t.B == 0 {
					fmt.Fprintf(&s.buf, "%s<nil>\n", specIndent(depth+1))
				}
			} else {
				s.node(nodeFromValue(v), depth+1)
			}
		case opKids:
			for _, el := range nodesFromSlice(fieldOf(node, specStr(t.A)), t.C != 0) {
				if el == nil && t.B != 0 {
					continue
				}
				s.node(el, depth+1)
			}
		case opHelper:
			for _, el := range valsFromSlice(fieldOf(node, specStr(t.A))) {
				if el == nil && t.B != 0 {
					continue
				}
				s.helper(specStr(t.C), el, depth+1)
			}
		case opSelfHelper:
			s.helper(specStr(t.A), node, depth)
		case opFree:
			if g := commentGroupOf(node, "FreeComments"); g != nil {
				fmt.Fprintf(&s.buf, "%sFreeComments: %d group(s)\n", specIndent(depth+1), len(g.List))
			}
		case opBetween:
			if g := commentGroupOf(node, "BetweenComments"); g != nil {
				fmt.Fprintf(&s.buf, "%sBetweenComments: %d group(s)\n", specIndent(depth+1), len(g.List))
			}
		case opTrailing:
			if g := commentGroupOf(node, "TrailingComments"); g != nil {
				fmt.Fprintf(&s.buf, "%sTrailingComments\n", specIndent(depth+1))
				s.commentGroup(g, depth+2)
			}
		case opClosing:
			if g := commentGroupOf(node, "ClosingBraceComment"); g != nil {
				fmt.Fprintf(&s.buf, "%sClosingBraceComment\n", specIndent(depth+1))
				s.commentGroup(g, depth+2)
			}
		case opImplements:
			if v := fieldOf(node, "Implements"); v.IsValid() && v.Len() > 0 {
				fmt.Fprintf(&s.buf, "%sImplements: %v\n", specIndent(depth+1), v.Interface())
			}
		case opAnnots:
			// AnnotationStatement entries are dumped by the caller (which holds
			// Options); the spec only records that the block exists.
		}
	}
}

func scalarWanted(policy, rend int, val string) bool {
	switch policy {
	case pNonEmpty:
		return val != ""
	case pTrue:
		return val == "true"
	case pNonZero:
		return val != "0"
	case pCount:
		return val != "0"
	}
	return true
}

func nodeFromValue(v reflect.Value) parser.Node {
	if isNilVal(v) {
		return nil
	}
	if n, ok := v.Interface().(parser.Node); ok {
		return n
	}
	return nil
}

// nodesFromSlice converts a slice field to []parser.Node.
//
// addr must be set when dump.go wrote `d.node(&n.F[i], ...)`: the element
// type then has its Node methods on the pointer receiver (MapLiteral.Pairs
// is a []MapPair value slice), so the element itself does not satisfy Node.
func nodesFromSlice(v reflect.Value, addr bool) []parser.Node {
	if !v.IsValid() || v.Kind() != reflect.Slice {
		return nil
	}
	out := make([]parser.Node, 0, v.Len())
	for i := 0; i < v.Len(); i++ {
		el := v.Index(i)
		if addr && el.CanAddr() {
			el = el.Addr()
		}
		if isNilVal(el) {
			out = append(out, nil)
			continue
		}
		if n, ok := el.Interface().(parser.Node); ok {
			out = append(out, n)
		} else {
			out = append(out, nil)
		}
	}
	return out
}

// valsFromSlice returns a slice field's elements as interface values, so
// non-Node helper structs (InterfaceMethod, TaggedEnumField,
// AnnotationStructField) can be dispatched too.
func valsFromSlice(v reflect.Value) []any {
	if !v.IsValid() || v.Kind() != reflect.Slice {
		return nil
	}
	out := make([]any, 0, v.Len())
	for i := 0; i < v.Len(); i++ {
		el := v.Index(i)
		if isNilVal(el) {
			out = append(out, nil)
			continue
		}
		out = append(out, el.Interface())
	}
	return out
}

func commentGroupOf(node parser.Node, field string) *parser.CommentGroup {
	v := fieldOf(node, field)
	if isNilVal(v) {
		return nil
	}
	if g, ok := v.Interface().(*parser.CommentGroup); ok {
		return g
	}
	return nil
}

// helper dispatches the three non-Node sub-structures.
func (s *specState) helper(name string, v any, depth int) {
	switch name {
	case "interfaceMethod":
		m, _ := v.(*parser.InterfaceMethod)
		if m == nil {
			fmt.Fprintf(&s.buf, "%s<nil>\n", specIndent(depth))
			return
		}
		var parts []string
		parts = append(parts, "name: "+m.Name)
		if m.Receiver != "" {
			parts = append(parts, "receiver: "+m.Receiver)
		}
		if m.IsVariadic {
			parts = append(parts, "variadic: true")
		}
		if m.IsGenericReceiver {
			parts = append(parts, "genericReceiver: true")
		}
		fmt.Fprintf(&s.buf, "%sInterfaceMethod{%s}\n", specIndent(depth), strings.Join(parts, ", "))
		for _, p := range m.Parameters {
			if p != nil {
				s.node(p, depth+1)
			}
		}
		for _, p := range m.Results {
			if p != nil {
				s.node(p, depth+1)
			}
		}
	case "taggedEnumField":
		f, _ := v.(*parser.TaggedEnumField)
		if f == nil {
			fmt.Fprintf(&s.buf, "%s<nil>\n", specIndent(depth))
			return
		}
		var parts []string
		parts = append(parts, "name: "+f.Name)
		if f.Type != nil {
			parts = append(parts, "type: "+f.Type.String())
		}
		fmt.Fprintf(&s.buf, "%sTaggedEnumField{%s}\n", specIndent(depth), strings.Join(parts, ", "))
		if f.Type != nil {
			s.node(f.Type, depth+1)
		}
	case "annotationStructField":
		f, _ := v.(*parser.AnnotationStructField)
		if f == nil {
			fmt.Fprintf(&s.buf, "%s<nil>\n", specIndent(depth))
			return
		}
		fmt.Fprintf(&s.buf, "%sAnnotationStructField{name: %s}\n", specIndent(depth), f.Name)
		if f.Value != nil {
			s.node(f.Value, depth+1)
		}
	case "annotationEntry":
		e, _ := v.(*parser.AnnotationEntry)
		if e == nil {
			fmt.Fprintf(&s.buf, "%s<nil>\n", specIndent(depth))
			return
		}
		var parts []string
		parts = append(parts, "key: "+e.Key)
		if e.Trailing {
			parts = append(parts, "trailing: true")
		}
		if e.Propagated {
			parts = append(parts, "propagated: true")
		}
		fmt.Fprintf(&s.buf, "%sAnnotationEntry{%s}\n", specIndent(depth), strings.Join(parts, ", "))
		if e.Value != nil {
			s.node(e.Value, depth+1)
		}
	default:
		panic("spec: unknown helper " + name)
	}
}

// ── the test ────────────────────────────────────────────────────────────

// TestSpecMatchesDump is the gate that makes the generated spec trustworthy.
// It walks the whole test corpus twice -- once with the real dumper, once with
// the spec interpreter -- and requires byte-identical output.  A failure here
// means the *table* is wrong, and there is no point porting it to Nolang.
func TestSpecMatchesDump(t *testing.T) {
	programs := parseCorpus(t)
	if len(programs) < 100 {
		t.Fatalf("corpus too small (%d parseable files); the test would be vacuous", len(programs))
	}
	paths := make([]string, 0, len(programs))
	for p := range programs {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	bad := 0
	for _, path := range paths {
		prog := programs[path]
		want := Dump(prog)
		got := specDump(prog)
		if want != got {
			bad++
			if bad <= 3 {
				t.Errorf("%s: spec disagrees with dump\n%s", path, firstDiff(want, got))
			}
		}
	}
	if bad > 0 {
		t.Fatalf("spec disagrees with dump on %d/%d files", bad, len(paths))
	}
	t.Logf("spec/dump agreement: %d files, byte-identical", len(paths))
}

func firstDiff(want, got string) string {
	wl := strings.Split(want, "\n")
	gl := strings.Split(got, "\n")
	for i := 0; i < len(wl) && i < len(gl); i++ {
		if wl[i] != gl[i] {
			lo := i - 2
			if lo < 0 {
				lo = 0
			}
			var b strings.Builder
			for j := lo; j < i+3 && j < len(wl); j++ {
				fmt.Fprintf(&b, "  line %d want: %q\n", j+1, wl[j])
			}
			for j := lo; j < i+3 && j < len(gl); j++ {
				fmt.Fprintf(&b, "  line %d got : %q\n", j+1, gl[j])
			}
			return b.String()
		}
	}
	return fmt.Sprintf("  lengths differ: want %d lines, got %d lines", len(wl), len(gl))
}

// TestSpecKindCount pins the size of the table.  If dump.go gains or loses a
// case, this fails and forces a regenerate; it also catches a generator that
// silently drops kinds.
func TestSpecKindCount(t *testing.T) {
	if got := len(specKinds) - 1; got != 71 {
		t.Fatalf("spec has %d kinds, want 71", got)
	}
}
